"""AI-Generated Unit Tests for QualityRiskScorer."""

import pytest
from quality_assessment.risk_scorer import QualityRiskScorer, RiskTier


class TestQualityRiskScorerAI:
    """Test suite generated by AI for QualityRiskScorer."""

    def test_default_init(self):
        """Test default weights initialization."""
        scorer = QualityRiskScorer()
        assert scorer.weights is not None
        assert "coverage_deficit" in scorer.weights

    def test_coverage_deficit_penalty(self):
        """Test coverage deficit penalty calculation."""
        scorer = QualityRiskScorer()
        assert scorer.calculate_coverage_deficit_penalty(100.0) == 0.0
        assert scorer.calculate_coverage_deficit_penalty(0.0) == 100.0

    def test_complexity_penalty_scaling(self):
        """Test complexity penalty function."""
        scorer = QualityRiskScorer()
        p1 = scorer.calculate_complexity_penalty(1.0)
        p2 = scorer.calculate_complexity_penalty(10.0)
        assert p1 == 0.0
        assert p2 > p1

    def test_composite_risk_nominal(self):
        """Test composite risk score generation."""
        scorer = QualityRiskScorer()
        res = scorer.calculate_composite_risk(
            coverage_pct=85.0,
            cyclomatic_complexity=3.0,
            churn_lines=20,
            smell_count=1,
            total_loc=200,
        )
        assert "risk_score" in res
        assert "tier" in res
        assert "breakdown" in res
        assert 0.0 <= res["risk_score"] <= 100.0

    def test_composite_risk_invalid_churn(self):
        """Test negative churn lines raises ValueError."""
        scorer = QualityRiskScorer()
        with pytest.raises(ValueError):
            scorer.calculate_composite_risk(80.0, 2.0, -10, 0, 100)
